import{_ as a,o as d,a as s,b as n}from"./app.C41L12d5.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"矩阵计算（ISASI）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_ISASI"},{"text":"Mmad计算","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/mmad_compute/mmad_compute"},{"text":"Conv2D（废弃）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/mmad_compute/Conv2D_deprecated"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/cube_compute_ISASI/mmad_compute/Conv2D_deprecated.md","filePath":"api/SIMD-API/basic_api/cube_compute_ISASI/mmad_compute/Conv2D_deprecated.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"数据类型","slug":"数据类型","link":"#数据类型"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788159000000}'),r={name:"api/SIMD-API/basic_api/cube_compute_ISASI/mmad_compute/Conv2D_deprecated.md"};function i(l,t,e,p,o,c){return d(),s("div",null,[...t[0]||(t[0]=[n(`<div><article class="markdown-body"><h1>Conv2D（废弃）</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：不支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p><strong>该接口废弃，并将在后续版本移除，请不要使用该接口。</strong></p><p>计算给定输入张量和权重张量的2-D卷积，输出结果张量。Conv2D卷积层多用于图像识别，使用过滤器提取图像中的特征。</p><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">U</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">Conv2D</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">U</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">featureMap</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">U</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">weight</span><span class="p">,</span><span class="w"> </span><span class="n">Conv2dParams</span><span class="o">&amp;</span><span class="w"> </span><span class="n">conv2dParams</span><span class="p">,</span><span class="w"> </span><span class="n">Conv2dTilling</span><span class="o">&amp;</span><span class="w"> </span><span class="n">tilling</span><span class="p">)</span>
</code></pre></div><p>入参中的tiling结构需要通过如下切分方案计算接口来获取：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="n">Conv2dTilling</span><span class="w"> </span><span class="n">GetConv2dTiling</span><span class="p">(</span><span class="n">Conv2dParams</span><span class="o">&amp;</span><span class="w"> </span><span class="n">conv2dParams</span><span class="p">)</span>
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 接口参数说明</p><table><thead><tr><th>参数名称</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数。<br><br><span data-filter="910">Atlas 训练系列产品，支持的TPosition为：CO1，CO2</span><br><span data-filter="310p">Atlas 推理系列产品AI Core，支持的TPosition为：CO1，CO2</span><br><br>结果中有效张量格式为[Cout/16, Ho, Wo, 16]，大小为Cout * Ho * Wo，Ho与Wo可以根据其他数据计算得出。<br>Ho = floor((H + pad_top + pad_bottom - dilation_h * (Kh - 1) - 1) / stride_h + 1)<br>Wo = floor((W + pad_left + pad_right - dilation_w * (Kw - 1) - 1) / stride_w + 1)<br>由于硬件要求Ho*Wo需为16倍数，在申请dst Tensor时，shape应向上16对齐，实际申请shape大小应为Cout * round_howo。<br>round_howo = ceil(Ho * Wo /16) * 16。</td></tr><tr><td>featureMap</td><td>输入</td><td>输入张量，Tensor的TPosition为A1。<br><br>输入张量&quot;feature_map&quot;的形状，格式是[C1, H, W, C0]。<br>C1*C0为输入的channel数，要求如下：<br>•当feature_map的数据类型为half时，C0=16。<br>•当feature_map的数据类型为int8_t时，C0=32。<br>• C1取值范围：[1,4]，输入的channel的范围：[16，32，64，128]。<br><br>H为高，取值范围：[1,40]。<br>W为宽，取值范围：[1,40]。</td></tr><tr><td>weight</td><td>输入</td><td>卷积核（权重）张量，Tensor的TPosition为B1。<br><br>卷积核张量&quot;weight&quot;的形状，格式是[C1, Kh, Kw, Cout, C0]。<br>C1*C0为输入的channel数，对于C0要求如下：<br>•当feature_map的数据类型为half时，C0=16。<br>•当feature_map的数据类型为int8_t时，C0=32。<br>• C1取值范围：[1,4]。<br>• kernel_shape输入的channel数需与fm_shape输入的channel数保持一致。<br><br>Cout为卷积核数目，取值范围：[16，32，64，128]，Cout必须为16的倍数。<br>Kh为卷积核高；值的范围：[1,5]。<br>Kw表示卷积核宽；值的范围：[1,5]。</td></tr><tr><td>conv2dParams</td><td>输入</td><td>输入矩阵形状等状态参数，类型为Conv2dParams。结构体具体定义为：<br><br><br>struct Conv2dParams {<br> uint32_t imgShape[CONV2D_IMG_SIZE]; // [H, W]<br> uint32_t kernelShapeIn[CONV2D_KERNEL_SIZE]; // [Kh, Kw]<br> uint32_t stride[CONV2D_STRIDE]; // [stride_h, stride_w]<br> uint32_t cin; // cin = C0 * C1;<br> uint32_t cout;<br> uint32_t padList[CONV2D_PAD]; // [pad_left, pad_right, pad_top, pad_bottom]<br> uint32_t dilation[CONV2D_DILATION]; // [dilation_h, dilation_w]<br> uint32_t initY;<br> uint32_t partialSum;<br>};<br></td></tr><tr><td>tilling</td><td>输入</td><td>分形控制参数，类型为Conv2dTilling。结构体具体定义为：<br><br>struct Conv2dTilling {<br> const uint32_t blockSize = 16; // # M block size is always 16<br> LoopMode loopMode = LoopMode::MODE_NM;<br><br> uint32_t c0Size = 32;<br> uint32_t dTypeSize = 1;<br><br> uint32_t strideH = 0;<br> uint32_t strideW = 0;<br> uint32_t dilationH = 0;<br> uint32_t dilationW = 0;<br> uint32_t hi = 0;<br> uint32_t wi = 0;<br> uint32_t ho = 0;<br> uint32_t wo = 0;<br><br> uint32_t height = 0;<br> uint32_t width = 0;<br><br> uint32_t howo = 0;<br><br> uint32_t mNum = 0;<br> uint32_t nNum = 0;<br> uint32_t kNum = 0;<br><br> uint32_t mBlockNum = 0;<br> uint32_t kBlockNum = 0;<br> uint32_t nBlockNum = 0;<br><br> uint32_t roundM = 0;<br> uint32_t roundN = 0;<br> uint32_t roundK = 0;<br><br> uint32_t mTileBlock = 0;<br> uint32_t nTileBlock = 0;<br> uint32_t kTileBlock = 0;<br><br> uint32_t mIterNum = 0;<br> uint32_t nIterNum = 0;<br> uint32_t kIterNum = 0;<br><br> uint32_t mTileNums = 0;<br><br> bool mHasTail = false;<br> bool nHasTail = false;<br> bool kHasTail = false;<br><br> uint32_t kTailBlock = 0;<br> uint32_t mTailBlock = 0;<br> uint32_t nTailBlock = 0;<br><br> uint32_t mTailNums = 0;<br>};<br></td></tr></tbody></table><p><strong>表2</strong> Conv2DParams结构体内参数说明：</p><table><thead><tr><th>参数名称</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>imgShape</td><td>vector&lt;int&gt;</td><td>输入张量&quot;feature_map&quot;的形状，格式是[H, W]。<br>• H为高，取值范围：[1,40]。<br>• W为宽，取值范围：[1,40]。</td></tr><tr><td>kernelShape</td><td>vector&lt;int&gt;</td><td>卷积核张量&quot;weight&quot;的形状，格式是[Kh, Kw]。<br>• Kh为高，取值范围：[1,5]。<br>• Kw为宽，取值范围：[1,5]。</td></tr><tr><td>stride</td><td>vector&lt;int&gt;</td><td>卷积步长，格式是[stride_h, stride_w]。<br>• stride_h表示步长高，值的范围：[1,4]。<br>• stride_w表示步长宽，值的范围：[1,4]。</td></tr><tr><td>cin</td><td>int</td><td>分形排布参数，Cin = C1 * C0，Cin为输入的channel数，C1取值范围：[1,4]。<br>•当feature_map的数据类型为float时，C0=8。输入的channel的范围：[8，16，24，32]。<br>•当feature_map的数据类型为half时，C0=16。输入的channel的范围：[16，32，48，64]。<br>•当feature_map的数据类型为int8_t时，C0=32。输入的channel的范围：[32，64，96，128]。</td></tr><tr><td>cout</td><td>int</td><td>Cout为卷积核数目，取值范围：[16，32，64，128]，Cout必须为16的倍数。</td></tr><tr><td>padList</td><td>vector&lt;int&gt;</td><td>padding行数/列数，格式是[pad_left, pad_right, pad_top, pad_bottom]。<br>• pad_left为feature_map左侧pad列数，范围[0,4]。pad_right为feature_map右侧pad列数，范围[0,4]。<br>• pad_top为feature_map顶部pad行数，范围[0,4]。<br>• pad_bottom为feature_map底部pad行数，范围[0,4]。</td></tr><tr><td>dilation</td><td>vector&lt;int&gt;</td><td>空洞卷积参数，格式[dilation_h, dilation_w]。<br>• dilation_h为空洞高，范围：[1,4]。<br>• dilation_w为空洞宽，范围：[1,4]。<br><br>膨胀后卷积核宽为dilation_w * (Kw - 1) + 1，高为dilation_h * (Kh - 1) + 1。</td></tr><tr><td>initY</td><td>uint32_t</td><td>表示dst是否需要初始化。<br>•取值0：不使用bias，L0C Buffer需要初始化，dst初始矩阵保存有之前结果，新计算结果会累加前一次Conv2D计算结果。<br>•取值1：不使用bias，L0C Buffer不需要初始化，dst初始矩阵中数据无意义，计算结果直接覆盖dst中的数据。</td></tr><tr><td>partialSum</td><td>uint32_t</td><td>当dst参数所在的TPosition为CO2时，通过该参数控制计算结果是否搬出。<br>•取值0：搬出计算结果<br>•取值1：不搬出计算结果，可以进行后续计算</td></tr></tbody></table><p><strong>表3</strong> Conv2dTilling结构体内参数说明</p><table><thead><tr><th>参数名称</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>blockSize</td><td>uint32_t</td><td>固定值，恒为16，一个维度内存放的元素个数。</td></tr><tr><td>loopMode</td><td>LoopMode</td><td>遍历模式，结构体具体定义为：<br><br>enum class LoopMode {<br> MODE_NM = 0,<br> MODE_MN = 1,<br> MODE_KM = 2,<br> MODE_KN = 3<br>};<br></td></tr><tr><td>c0Size</td><td>uint32_t</td><td>一个block的字节长度，范围[16或者32]。</td></tr><tr><td>dtypeSize</td><td>uint32_t</td><td>传入的数据类型的字节长度，范围[1, 2]。</td></tr><tr><td>strideH</td><td>uint32_t</td><td>卷积步长-高，范围:[1,4]。</td></tr><tr><td>strideW</td><td>uint32_t</td><td>卷积步长-宽，范围:[1,4]。</td></tr><tr><td>dilationH</td><td>uint32_t</td><td>空洞卷积参数-高，范围：[1,4]。</td></tr><tr><td>dilationW</td><td>uint32_t</td><td>空洞卷积参数-宽，范围：[1,4]。</td></tr><tr><td>hi</td><td>uint32_t</td><td>feature_map形状-高，范围：[1,40]。</td></tr><tr><td>wi</td><td>uint32_t</td><td>feature_map形状-宽，范围：[1,40]。</td></tr><tr><td>ho</td><td>uint32_t</td><td>feature_map形状-高，范围：[1,40]。</td></tr><tr><td>wo</td><td>uint32_t</td><td>feature_map形状-宽，范围：[1,40]。</td></tr><tr><td>height</td><td>uint32_t</td><td>weight形状-高，[1,5]。</td></tr><tr><td>width</td><td>uint32_t</td><td>weight形状-宽，[1,5]。</td></tr><tr><td>howo</td><td>uint32_t</td><td>feature_map形状大小，为ho * wo。</td></tr><tr><td>mNum</td><td>uint32_t</td><td>M轴等效数据长度参数值，范围：[1,4096]。</td></tr><tr><td>nNum</td><td>uint32_t</td><td>N轴等效数据长度参数值，范围：[1,4096]。</td></tr><tr><td>kNum</td><td>uint32_t</td><td>K轴等效数据长度参数值，范围：[1,4096]。</td></tr><tr><td>roundM</td><td>uint32_t</td><td>M轴等效数据长度参数值且以blockSize为倍数向上取整，范围：[1,4096]。</td></tr><tr><td>roundN</td><td>uint32_t</td><td>N轴等效数据长度参数值且以blockSize为倍数向上取整，范围：[1,4096]。</td></tr><tr><td>roundK</td><td>uint32_t</td><td>K轴等效数据长度参数值且以c0Size为倍数向上取整，范围：[1,4096]。</td></tr><tr><td>mBlockNum</td><td>uint32_t</td><td>M轴Block个数，mBlockNum = mNum / blockSize，范围：[1,4096]。</td></tr><tr><td>nBlockNum</td><td>uint32_t</td><td>N轴Block个数，nBlockNum = nNum / blockSize，范围：[1,4096]。</td></tr><tr><td>kBlockNum</td><td>uint32_t</td><td>K轴Block个数，kBlockNum = kNum / blockSize，范围：[1,4096]。</td></tr><tr><td>mIterNum</td><td>uint32_t</td><td>遍历M轴维度数量，范围：[1,4096]。</td></tr><tr><td>nIterNum</td><td>uint32_t</td><td>遍历N轴维度数量，范围：[1,4096]。</td></tr><tr><td>kIterNum</td><td>uint32_t</td><td>遍历K轴维度数量，范围：[1,4096]。</td></tr><tr><td>mTileBlock</td><td>uint32_t</td><td>M轴切分块个数，范围：[1,4096]。</td></tr><tr><td>nTileBlock</td><td>uint32_t</td><td>N轴切分块个数，范围：[1,4096]。</td></tr><tr><td>kTileBlock</td><td>uint32_t</td><td>K轴切分块个数，范围：[1,4096]。</td></tr><tr><td>kTailBlock</td><td>uint32_t</td><td>K轴尾块个数，范围：[1,4096]。</td></tr><tr><td>mTailBlock</td><td>uint32_t</td><td>M轴尾块个数，范围：[1,4096]。</td></tr><tr><td>nTailBlock</td><td>uint32_t</td><td>N轴尾块个数，范围：[1,4096]。</td></tr><tr><td>kHasTail</td><td>bool</td><td>K轴是否存在尾块。</td></tr><tr><td>mHasTail</td><td>bool</td><td>M轴是否存在尾块。</td></tr><tr><td>nHasTail</td><td>bool</td><td>N轴是否存在尾块。</td></tr><tr><td>mTileNums</td><td>uint32_t</td><td>M轴切分块个数的长度，范围：[1,4096]。</td></tr><tr><td>mTailNums</td><td>uint32_t</td><td>M轴尾块个数的长度，范围：[1,4096]。</td></tr></tbody></table><h2 id="数据类型">数据类型<a class="header-anchor" href="#数据类型">​</a></h2><p><strong>表4</strong> feature_map、weight和dst的数据类型组合</p><table><thead><tr><th>feature_map.dtype</th><th>weight.dtype</th><th>dst.dtype</th></tr></thead><tbody><tr><td>int8_t</td><td>int8_t</td><td>int32_t</td></tr><tr><td>half</td><td>half</td><td>float</td></tr><tr><td>half</td><td>half</td><td>half</td></tr></tbody></table><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li>该接口当前不支持W=Kw并且H&gt;Kh的场景，其将产生不可预期的结果。</li><li>操作数地址对齐要求请参见<a href="../../../general_description_and_constraints.html#section796754519912">通用地址对齐约束</a>。</li></ul><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><p>该接口已废弃，请使用Mmad接口替代。</p></article></div>`,1)])])}const b=a(r,[["render",i]]);export{u as __pageData,b as default};
